css:
#tongsci2-2-2-1-1-cover .frame { flex-direction: row; gap: 72px; }
#tongsci2-2-2-1-1-cover .col-text { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 28px; }
#tongsci2-2-2-1-1-cover h1 { font-size: 112px; }
#tongsci2-2-2-1-1-cover .hero-pen { font-size: 56px; transform: rotate(-1.2deg); transform-origin: left center; margin-top: -6px; }
#tongsci2-2-2-1-1-cover .footer { left: 1100px; right: 300px; }
#tongsci2-2-2-1-1-cover .lesson-chip {
  align-self: flex-start; display: inline-flex; gap: 14px; align-items: baseline;
  border: 2px solid var(--ink); border-radius: 999px; padding: 6px 22px; font-size: 26px; font-weight: 600;
}
#tongsci2-2-2-1-1-cover .lesson-chip span { font-family: var(--f-mono); font-size: 22px; color: var(--ink-2); font-weight: 500; }
#tongsci2-2-2-1-1-cover .goals { display: flex; flex-direction: column; gap: 18px; max-width: 980px; }
#tongsci2-2-2-1-1-cover .goals-label { font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--ink-2); }
#tongsci2-2-2-1-1-cover .goal { display: grid; grid-template-columns: 52px 1fr; gap: 6px; font-size: 30px; line-height: 1.42; }
#tongsci2-2-2-1-1-cover .goal .no { font-family: var(--f-display); font-weight: 700; color: var(--ink-2); }
#tongsci2-2-2-1-1-cover .today {
  margin-top: 6px; padding: 20px 28px; background: var(--paper-2); border: 2px solid var(--ink);
  border-radius: 6px; box-shadow: 6px 6px 0 var(--ink); font-size: 32px; line-height: 1.45;
}
#tongsci2-2-2-1-1-cover .today .tag { display: block; font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--accent); margin-bottom: 6px; }
#tongsci2-2-2-1-1-cover .col-fig { flex: 0 0 700px; display: flex; flex-direction: column; gap: 14px; padding-top: 24px; }
#tongsci2-2-2-1-1-cover .fig-caption .cap { font-size: 21px; line-height: 1.4; }
#tongsci2-2-2-1-1-cover .share-card { padding: 60px 30px 26px; display: flex; flex-direction: column; gap: 18px; }
#tongsci2-2-2-1-1-cover .share-card h3 { margin: 0; font: 700 34px/1.3 var(--f-display); color: var(--ink); text-wrap: balance; }

js:
/* tongsci2.2-2-1.1.cover */
(function () {
  'use strict';
  const { part, D } = window.Deck;
  const L1 = window.L1;
  // 체험 장 해 볼 일 ①②③(2-1-1 frame.js 방식): 지금 단계 번호(0 = 끝)
  const mark = (root, n, max = 3) => { const ok = []; for (let k = 1; k <= max; k++) if (n === 0 || k < n) ok.push(k); L1.steps(root, n, ok); L1.done(root, n === 0); };
  // 기존 조작 모듈은 고치지 않고, 장이 보이는 동안 상태를 읽어 해 볼 일을 맞춘다
  const watch = (root, fn) => { let id = 0; const run = () => mark(root, fn()); run(); return { setActive(on) { clearInterval(id); if (on) id = setInterval(run, 250); run(); } }; };
  window.SunMark = { mark, watch };

  // 1. 표지: 이글거리는 태양 · 예측 하나 고르기 · 시간 막대(석탄이라면 수천 년 vs 약 50억 년)
  part('tongsci2-2-2-1-1-cover', (root) => {
    const sun = window.SunGlow.mount(root.querySelector('.sun-cv'));
    const opts = [...root.querySelectorAll('.share-opts button')];
    opts.forEach((b) => b.addEventListener('click', () => {
      const on = b.getAttribute('aria-pressed') !== 'true';
      opts.forEach((x) => x.setAttribute('aria-pressed', String(on && x === b)));
    }));
    const coal = root.querySelector('.age-row.coal b i'), real = root.querySelector('.age-row.sun b i');
    const bars = (on, instant) => {
      // 수천 년 ÷ 50억 년 ≈ 100만분의 1 → 막대로는 선 하나(3px)
      if (!window.gsap || instant) { coal.style.width = on ? '3px' : '0'; real.style.width = on ? '100%' : '0'; return; }
      gsap.fromTo(real, { width: '0%' }, { width: on ? '100%' : '0%', duration: D(1.6), ease: 'power2.inOut', delay: D(0.25) });
      gsap.fromTo(coal, { width: '0px' }, { width: on ? '3px' : '0px', duration: D(0.2), delay: D(0.25) });
    };
    return {
      setActive: (on) => sun.setActive(on),
      fit: () => sun.fit(),
      fragment(f, on) { if (f.dataset.anim === 'age') bars(on); },
      sync(slide) { const f = slide.querySelector('[data-anim="age"]'); bars(f.classList.contains('visible'), true); },
    };
  });

  // 2. 여러 가지 에너지: 줄마다 에너지를 고르면 그 물건 그림이 왼쪽 에너지 상자(카드)로 들어간다.
  //    맞으면 초록 테로 남고, 틀리면 상자가 흔들리며 힌트가 뜨고 물건이 빠져나온다. 카드를 누르면 뜻(뒷면)
})();
